contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We test the behavior of c.sendMoney when called by the owner (this contract).
    // Parameters:
    // - target: address to forward to
    // - value: wei to pass to sendMoney (must be available in this contract)
    function run(address target, uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value);

        // Observe before state
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // Top-level state-changing call on c: only c.sendMoney fits the shape and is state-changing.
        bool reverted;
        c.sendMoney(target, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after state
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // Rule: If the call reverted then neither C.balance nor depositsCount increased;
        // if it succeeded then C.balance increased by at most value and depositsCount did not decrease.
        assert(
            (reverted && afterBal == beforeBal && afterCount >= beforeCount)
            || (!reverted && afterBal <= beforeBal + value && afterCount >= beforeCount)
        );
    }

    // Allow receiving Ether from C.withdraw or transferred calls
    receive() external payable {}
}

